#ifndef HWINFO_H
#define HWINFO_H

#include <napi.h>
#include <set>
#include <queue>

enum class LogLevel {
    Debug,
    Info,
    Warning,
    Error,
};

struct LogMsg {
    LogLevel level;
    std::string msg;
};

class HWInfo : public Napi::ObjectWrap<HWInfo>
{
public:
    static Napi::Object Init(Napi::Env env, Napi::Object exports);
    HWInfo(const Napi::CallbackInfo &info);
    ~HWInfo();
    void SetInited(bool inited);
    bool GetInited();

private:
    Napi::Value Init(const Napi::CallbackInfo &info);
    Napi::Value IsInited(const Napi::CallbackInfo &info);
    Napi::Value Status(const Napi::CallbackInfo &info);
    Napi::Value Spec(const Napi::CallbackInfo &info);
    Napi::Value Details(const Napi::CallbackInfo &info);
    Napi::Value DeInit(const Napi::CallbackInfo &info);

    Napi::Value SetStatusFilter(const Napi::CallbackInfo &info);
    Napi::Value SetMaxSensorTimeout(const Napi::CallbackInfo &info);
    Napi::Value SetLogHandler(const Napi::CallbackInfo &info);

public:
    bool WaitForInit(void);
    // void Log(std::string msg);
    void Log(LogLevel level, const char *format, ...);

    Napi::Function logCallback;
    int flag = 0;
    std::set<std::string> keywords;
    std::set<int> disableSensors;
    bool inited = false;
    bool sensorChecked = false;
    int maxSensorTimeout = 2000; // ms

    // Napi::ThreadSafeFunction _tsfn;
    // std::thread _thread;
    // std::queue<LogMsg> logQueue;
};

#endif // HWINFO_H
